const items = $input.all();
const aiResponse = items[0].json.message.content;
let parsed;
try {
  parsed = JSON.parse(aiResponse);
} catch(e) {
  parsed = { summary: aiResponse, decisions: [], action_items: [], follow_ups: [] };
}
const meetingTitle = items[0].json.body?.meeting_title || 'Untitled Meeting';
const attendees = items[0].json.body?.attendees || '';
const meetingDate = items[0].json.body?.date || new Date().toISOString().split('T')[0];

const actionItemsList = (parsed.action_items || []).map(a => `- ${a.task} (Assignee: ${a.assignee || 'TBD'}, Deadline: ${a.deadline || 'TBD'})`).join('\n');
const summaryBullets = Array.isArray(parsed.summary) ? parsed.summary.map(s => `- ${s}`).join('\n') : parsed.summary;

return [{
  json: {
    meetingTitle,
    meetingDate,
    attendees,
    summary: summaryBullets,
    decisions: Array.isArray(parsed.decisions) ? parsed.decisions.join(', ') : (parsed.decisions || ''),
    actionItems: actionItemsList,
    followUps: Array.isArray(parsed.follow_ups) ? parsed.follow_ups.join(', ') : (parsed.follow_ups || ''),
    rawAiResponse: aiResponse
  }
}];
